const b64 = "";

const fs = require("fs");
const path = require("path");
const { execSync } = require("child_process");

console.log("--> Gravando sprite sheet da animacao de vitoria (caso resolvido)...");
const targetPath = "public/assets/aistudio/Detetive_Pixelado_no_Ref_gio_Aconchegante_674d8c38.png";
const dir = path.dirname(targetPath);
if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(targetPath, Buffer.from(b64, "base64"));
console.log(" Gravado com sucesso: " + targetPath);

console.log("\n--> Subindo para o GitHub e Surge...");
try {
    execSync("git add \"" + targetPath + "\"", { stdio: "inherit" });
    execSync("git commit -m \"feat: adicionar sprite da animacao de caso resolvido (brinde lareira)\"", { stdio: "inherit" });
    execSync("git push origin master --force", { stdio: "inherit" });
    execSync("npm run deploy", { stdio: "inherit" });
    console.log("\n SUCESSO! Animacao de caso resolvido publicada no Surge!");
} catch (e) {
    console.log("Erro:", e.message);
}
